        this.closeBtn.addEventListener("click", function(){ self.dispatchEvent(new CustomEvent("cds-close", { bubbles: true })); if (self.mobile) self.close(); });
        this._mq = window.matchMedia ? matchMedia("(max-width: 743px)") : null;
