    shuffle(a){ var b = a.slice(), ok = a.length < 2; do { for (var i = b.length - 1; i > 0; i--){ var j = Math.floor(Math.random() * (i + 1)), t = b[i]; b[i] = b[j]; b[j] = t; } } while (!ok && b.every(function(x, k){ return x === a[k]; })); return b; }
